// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MultiplicatorX3} from "../src/MultiplicatorX3.sol";

contract InvMutTest is Test {
    MultiplicatorX3 c;
    address payable owner;

    function setUp() public {
        // Owner must be a recipient that reliably accepts ETH transfers.
        owner = payable(address(new Payee()));
        vm.prank(owner);
        c = new MultiplicatorX3();
    }

    function testFuzz_property(uint256 amount) public {
        // Admissible domain: any pre-existing balance of at least 2 wei.
        amount = bound(amount, 2, 1e30);

        // Fund the victim contract with the fuzzed amount.
        vm.deal(address(c), amount);

        // Owner drains the contract via withdraw().
        vm.prank(owner);
        c.withdraw();

        // General rule: after a successful owner withdraw(), NO Ether stays in c.
        // P: transfers the whole balance -> balance == 0 for every admissible amount.
        // M: transfers only 1 wei -> balance == amount - 1 >= 1, rule breaks.
        assertTrue(address(c).balance == 0, "withdraw must drain the entire balance");
    }
}

// Minimal live recipient the contract (owned by it) can transfer to.
contract Payee {
    receive() external payable {}
}
